export function searchStations(query: string, limit = 8): Station[] {
  const q = query.trim().toUpperCase();
  if (q.length < 1) return [];
  const scored: Array<{ s: Station; rank: number }> = [];
  for (const s of STATIONS) {
    const code = s.code;
    const nameU = s.name.toUpperCase();
    let rank = -1;
    if (code.startsWith(q)) rank = 0;
    else if (nameU.startsWith(q)) rank = 1;
    else if (code.includes(q)) rank = 2;
    else if (nameU.includes(q)) rank = 3;
    if (rank >= 0) scored.push({ s, rank });
  }
  scored.sort((a, b) => a.rank - b.rank || a.s.name.localeCompare(b.s.name));
  return scored.slice(0, limit).map((x) => x.s);
}
